  window.ChittiBreakdownKB = {
    t: t, lang: lang,
    bike: BIKE, car: CAR,
    disclaimer: m('Self-repair has real risks — hot engine, fuel, a car on a jack. If a step feels unsafe or you are unsure, stop and call for help. Chitti is a guide, not a liability.', 'खुद मरम्मत में असली ख़तरे हैं — गरम इंजन, ईंधन, जैक पर खड़ी कार। अगर कोई स्टेप असुरक्षित लगे या आप अनिश्चित हों, रुकें और मदद बुलाएँ। Chitti एक गाइड है, ज़िम्मेदारी नहीं।', 'சுயமாக பழுது பார்ப்பதில் உண்மையான ஆபத்துகள் உள்ளன — சூடான இன்ஜின், ஃபியூல், ஜாக்கில் நிற்கும் கார். ஒரு படி பாதுகாப்பற்றதாகத் தோன்றினால் அல்லது நிச்சயமில்லாவிட்டால், நிறுத்தி உதவி அழைக்கவும். Chitti ஒரு வழிகாட்டி, பொறுப்பல்ல.', 'స్వయంగా మరమ్మతు చేయడంలో నిజమైన ప్రమాదాలున్నాయి — వేడి ఇంజిన్, ఫ్యూయల్, జాక్‌పై ఉన్న కారు. ఒక స్టెప్ సురక్షితం కాదని అనిపిస్తే లేదా అనుమానం ఉంటే, ఆపి సహాయం పిలవండి. Chitti ఒక గైడ్, బాధ్యత కాదు.', 'নিজে মেরামতে আসল ঝুঁকি আছে — গরম ইঞ্জিন, ফুয়েল, জ্যাকে দাঁড়ানো গাড়ি। কোনো ধাপ অনিরাপদ মনে হলে বা নিশ্চিত না হলে, থামুন ও সাহায্য ডাকুন। Chitti একটি গাইড, দায়বদ্ধতা নয়।', 'स्वतः दुरुस्ती करण्यात खरे धोके आहेत — गरम इंजिन, इंधन, जॅकवर उभी कार. एखादी पायरी असुरक्षित वाटल्यास किंवा खात्री नसल्यास, थांबा आणि मदत बोलवा. Chitti एक मार्गदर्शक आहे, जबाबदारी नाही.', 'જાતે રિપેર કરવામાં ખરા જોખમ છે — ગરમ એન્જિન, ફ્યુઅલ, જેક પર ઊભી કાર. કોઈ સ્ટેપ અસલામત લાગે કે ખાતરી ન હોય તો, રોકો અને મદદ બોલાવો. Chitti એક ગાઇડ છે, જવાબદારી નહીં.', 'ಸ್ವತಃ ದುರಸ್ತಿ ಮಾಡುವುದರಲ್ಲಿ ನಿಜವಾದ ಅಪಾಯಗಳಿವೆ — ಬಿಸಿ ಇಂಜಿನ್, ಫ್ಯೂಯಲ್, ಜ್ಯಾಕ್‌ನಲ್ಲಿ ನಿಂತ ಕಾರು. ಒಂದು ಹಂತ ಅಸುರಕ್ಷಿತ ಎನಿಸಿದರೆ ಅಥವಾ ಖಚಿತವಿಲ್ಲದಿದ್ದರೆ, ನಿಲ್ಲಿಸಿ ಸಹಾಯ ಕರೆಯಿರಿ. Chitti ಒಂದು ಮಾರ್ಗದರ್ಶಿ, ಹೊಣೆಗಾರಿಕೆ ಅಲ್ಲ.', 'സ്വയം റിപ്പയർ ചെയ്യുന്നതിൽ യഥാർത്ഥ അപകടങ്ങളുണ്ട് — ചൂടുള്ള എഞ്ചിൻ, ഫ്യൂവൽ, ജാക്കിൽ നിൽക്കുന്ന കാർ. ഒരു സ്റ്റെപ്പ് സുരക്ഷിതമല്ലെന്ന് തോന്നിയാൽ അല്ലെങ്കിൽ ഉറപ്പില്ലെങ്കിൽ, നിർത്തി സഹായം വിളിക്കുക. Chitti ഒരു ഗൈഡ് ആണ്, ബാധ്യത അല്ല.'),
    forVehicle: function (v) { return v === '4w' || v === 'car' ? CAR : BIKE; }
  };
